import { bindExpressionBoxInputs, createExpressionBoxLookup, expressionBoxLookupMarkup } from '../../../packages/paramagic-core/src/modules/ExpressionBox.js';
const unbind = bindExpressionBoxInputs(document);
const textarea = document.querySelector('textarea');
textarea.insertAdjacentHTML('afterend', expressionBoxLookupMarkup());
const multiline = createExpressionBoxLookup({field:textarea,listbox:textarea.nextElementSibling});
const options = () => [...document.querySelector('datalist').options].map(o=>({value:o.value,label:o.label}));
multiline.setOptions(options());
const input = document.querySelector('[aria-label="Shared input expression"]');
input.addEventListener('keydown', event => { if (event.key === 'Enter') input.blur(); });
const result = document.querySelector('#result');
const key = (field, key, extra = {}) => field.dispatchEvent(new KeyboardEvent('keydown',{key,bubbles:true,cancelable:true,...extra}));
const type = (field,value) => {field.value=value;field.setSelectionRange(value.length,value.length);field.dispatchEvent(new Event('input',{bubbles:true}));};
const list = () => document.querySelector('.expression-box-lookup-list:not([hidden])');
document.querySelector('#run').addEventListener('click',async()=>{
 const passed=[];
 const assert = (condition,label) => {if(!condition)throw new Error(label);passed.push(label);};
 try {
  input.focus();type(input,'2 * W');
  assert(list()?.children.length===2,'Input filters the current token');
  key(input,'ArrowDown');key(input,'Enter');
  assert(input.value==='2 * Width','Keyboard selection preserves the expression prefix');
  assert(document.activeElement===input,'Suggestion selection precedes tool-owned Enter-to-blur handlers');
  let changes=0;input.addEventListener('change',()=>changes++,{once:true});
  type(input,'H');list().firstElementChild.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true}));
  assert(input.value==='Height' && changes===1,'Pointer selection commits an input change');
  type(input,'W');const before=input.value;key(input,'Escape');
  assert(!list() && input.value===before,'Escape dismisses without changing the expression');
  type(input,'W');const properties=['backgroundColor','color','fontFamily','fontSize','padding','borderRadius','boxShadow'];
  const inputStyle=properties.map(p=>getComputedStyle(list())[p]);
  textarea.focus();await Promise.resolve();type(textarea,'2 * W');
  const textareaStyle=properties.map(p=>getComputedStyle(list())[p]);
  assert(JSON.stringify(inputStyle)===JSON.stringify(textareaStyle),'Input and textarea popup styles are identical');
  key(textarea,'ArrowDown');
  assert(key(textarea,'Enter',{shiftKey:true}),'Shift+Enter remains available for a newline');
  type(textarea,'2 * Width\n+ H');key(textarea,'ArrowDown');key(textarea,'Tab');
  assert(textarea.value==='2 * Width\n+ Height','Multiline token selection preserves previous lines');
  input.focus();await Promise.resolve();
  const option=document.createElement('option');option.value='Depth';document.querySelector('datalist').append(option);
  type(input,'D');assert(list()?.firstElementChild?.textContent==='Depth','Input reads newly added symbols without rebinding');option.remove();
  type(input,'Z');assert(!list(),'No-match queries hide the list');
  const bottom=document.querySelector('[aria-label="Bottom edge expression"]');bottom.focus();type(bottom,'W');
  assert(list().getBoundingClientRect().bottom<=bottom.getBoundingClientRect().top,'Bottom-edge popup opens above the field');
  bottom.blur();await Promise.resolve();await Promise.resolve();
  assert(!list(),'Blur dismisses the popup');
  assert(document.querySelectorAll('.expression-box-lookup-list').length===1,'Input popups are removed when focus leaves');
  result.textContent='PASS: '+passed.length+' checks\n'+passed.join('\n');
 } catch(error){result.textContent='FAIL: '+error.message+'\n'+passed.join('\n');throw error;}
});
if(import.meta.hot)import.meta.hot.dispose(()=>{unbind();multiline.destroy();});
